import { join } from "path";

/**
 * Resolve a writable directory for server-side persistence (analytics, LLM
 * cache, etc.).
 *
 * On Vercel Functions only `/tmp` is writable, and it lives only as long as
 * the warm container — so persistence does not survive cold starts. In dev
 * and self-hosted deployments we write to the repo's `data/` dir for durable
 * cross-restart storage.
 */
export function dataDir(...subpaths: string[]): string {
  const base = process.env.VERCEL ? "/tmp" : join(process.cwd(), "data");
  return subpaths.length > 0 ? join(base, ...subpaths) : base;
}
=== PERSIST ===
import { appendFileSync, readFileSync, writeFileSync, mkdirSync, existsSync } from "fs";
import { join } from "path";
import type { AnalyticsEntry } from "@/app/lib/types/analytics";
import { dataDir } from "@/app/lib/utils/dataDir";

// On Vercel, analytics history doesn't persist across cold starts — see
// Deploy to Vercel in README. See dataDir() for the underlying rationale.
const DATA_DIR = dataDir();
const FILE_PATH = join(DATA_DIR, "analytics.jsonl");

function ensureDir() {
  if (!existsSync(DATA_DIR)) {
    mkdirSync(DATA_DIR, { recursive: true });
  }
}

export function appendAnalyticsEntry(entry: AnalyticsEntry): void {
  ensureDir();
  appendFileSync(FILE_PATH, JSON.stringify(entry) + "\n", "utf-8");
}

export function readAnalyticsEntries(): AnalyticsEntry[] {
  if (!existsSync(FILE_PATH)) return [];
  const content = readFileSync(FILE_PATH, "utf-8");
  const entries: AnalyticsEntry[] = [];
  for (const line of content.split("\n")) {
    if (!line.trim()) continue;
    try {
      entries.push(JSON.parse(line));
    } catch {
      // skip corrupt lines
    }
  }
  return entries;
}

export function clearAnalyticsEntries(): void {
  ensureDir();
  writeFileSync(FILE_PATH, "", "utf-8");
}
=== CACHE ===
import { createHash } from "crypto";
import { readFile, writeFile, mkdir, unlink } from "fs/promises";
import { join } from "path";
import { dataDir } from "@/app/lib/utils/dataDir";
import type { LlmCallUsage } from "./callLlm";

const CACHE_DIR = dataDir("cache");

type CachedResult = {
  text: string;
  usage: LlmCallUsage;
};

type CachedResultWithHash = CachedResult & { cacheHash: string };

export function computeHash(
  model: string,
  systemPrompt: string,
  userContent: string,
  maxTokens: number
): string {
  return createHash("sha256")
    .update(JSON.stringify({ model, systemPrompt, userContent, maxTokens }))
    .digest("hex");
}

let dirEnsured = false;
async function ensureCacheDir() {
  if (dirEnsured) return;
  await mkdir(CACHE_DIR, { recursive: true });
  dirEnsured = true;
}

export async function getCachedResult(
  model: string,
  systemPrompt: string,
  userContent: string,
  maxTokens: number
): Promise<CachedResultWithHash | null> {
  const hash = computeHash(model, systemPrompt, userContent, maxTokens);
  const filePath = join(CACHE_DIR, `${hash}.json`);

  try {
    const data = JSON.parse(await readFile(filePath, "utf-8")) as CachedResult;
    // Override usage to reflect cache hit
    return {
      text: data.text,
      usage: {
        ...data.usage,
        provider: "cache",
        costUsd: 0,
        latencyMs: 0,
      },
      cacheHash: hash,
    };
  } catch {
    // Corrupt or missing cache file — treat as miss
    return null;
  }
}

