1	import { createHash } from "crypto";
2	import { readFile, writeFile, mkdir, unlink } from "fs/promises";
3	import { join } from "path";
4	import { dataDir } from "@/app/lib/utils/dataDir";
5	import type { LlmCallUsage } from "./callLlm";
6	
7	const CACHE_DIR = dataDir("cache");
8	
9	type CachedResult = {
10	  text: string;
11	  usage: LlmCallUsage;
12	};
13	
14	type CachedResultWithHash = CachedResult & { cacheHash: string };
15	
16	export function computeHash(
17	  model: string,
18	  systemPrompt: string,
19	  userContent: string,
20	  maxTokens: number
21	): string {
22	  return createHash("sha256")
23	    .update(JSON.stringify({ model, systemPrompt, userContent, maxTokens }))
24	    .digest("hex");
25	}
26	
27	let dirEnsured = false;
28	async function ensureCacheDir() {
29	  if (dirEnsured) return;
30	  await mkdir(CACHE_DIR, { recursive: true });
31	  dirEnsured = true;
32	}
33	
34	export async function getCachedResult(
35	  model: string,
36	  systemPrompt: string,
37	  userContent: string,
38	  maxTokens: number
39	): Promise<CachedResultWithHash | null> {
40	  const hash = computeHash(model, systemPrompt, userContent, maxTokens);
41	  const filePath = join(CACHE_DIR, `${hash}.json`);
42	
43	  try {
44	    const data = JSON.parse(await readFile(filePath, "utf-8")) as CachedResult;
45	    // Override usage to reflect cache hit
46	    return {
47	      text: data.text,
48	      usage: {
49	        ...data.usage,
50	        provider: "cache",
51	        costUsd: 0,
52	        latencyMs: 0,
53	      },
54	      cacheHash: hash,
55	    };
56	  } catch {
57	    // Corrupt or missing cache file — treat as miss
58	    return null;
59	  }
60	}
61	
62	export async function setCachedResult(
63	  hash: string,
64	  result: CachedResult
65	): Promise<void> {
66	  await ensureCacheDir();
67	  const filePath = join(CACHE_DIR, `${hash}.json`);
68	  await writeFile(filePath, JSON.stringify(result, null, 2), "utf-8");
69	}
70	
71	export async function removeCachedResult(
72	  model: string,
73	  systemPrompt: string,
74	  userContent: string,
75	  maxTokens: number,
76	): Promise<void> {
77	  const hash = computeHash(model, systemPrompt, userContent, maxTokens);
78	  const filePath = join(CACHE_DIR, `${hash}.json`);
79	  try {
80	    await unlink(filePath);
81	  } catch {
82	    // File doesn't exist — nothing to remove
83	  }
84	}
