/** Record analytics and write to cache (same as callLlm's recordAndCache). */
async function recordAndCache(
  endpoint: string,
  usage: LlmCallUsage,
  text: string,
  cacheHash: string,
): Promise<void> {
  try {
    appendAnalyticsEntry({
      id: randomUUID(),
